{
  "summary": "Implement the triage.sh script to filter ERROR logs, extract stable signatures by removing variable parameters, and count occurrences. Output format is '<count> <signature>'.",
  "files": [
    {
      "path": "scripts/triage.sh",
      "content": "#!/usr/bin/env bash\nset -euo pipefail\n\n# Filter ERROR lines, remove variable parameters (key=value), count signatures\ngrep \" ERROR \" \"$1\" | \\\n  sed 's/ [^ ]*=[^ ]*//g' | \\\n  sort | \\\n  uniq -c | \\\n  sed 's/^ *//'\n"
    }
  ]
}
